import os,re,json,collections
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def comps(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
                v=g[r][c]; st=[(r,c)]; comp=set()
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==v and (ny,nx) not in seen:
                            st.append((ny,nx))
                out.append((v,sorted(comp)))
    return out

def f(g):
    H,W=len(g),len(g[0])
    orig=comps(g)
    res=[r[:] for r in g]
    # 1. horizontal single-gap fill
    for r in range(H):
        for c in range(W-2):
            if res[r][c]!=0 and res[r][c]==res[r][c+2]:
                res[r][c+1]=res[r][c]
    out=[r[:] for r in res]
    # 2. vertical: items from ORIGINAL components (unchanged by gap fill order)
    for c in range(W):
        line=sorted([(min(p[0] for p in comp if p[1]==cc), max(p[0] for p in comp if p[1]==cc), v)
                     for v,comp in orig
                     for cc in {p[1] for p in comp}
                     if c==cc and any(p[1]==c for p in comp)])
        prev=None
        for top,bot,v in line:
            if prev is None:
                for rr in range(top):
                    if out[rr][c]==0: out[rr][c]=v
            else:
                for rr in range(prev+1,top):
                    if out[rr][c]==0: out[rr][c]=v
            prev=bot
    return out

